const results=[],errors=[],external=[],requests=[];
let lastPage;
const lunch=Date.parse('2026-10-11T12:00:00+08:00'),owner='qinghe.owner@mealforward.invalid';
const fixture=()=>{const s=M.initialState(lunch);s.clockOffset=lunch-Date.now();return s;};
const saved=page=>page.evaluate(key=>JSON.parse(localStorage.getItem(key)),M.KEY);
async function fresh(width=1440,s=fixture(),blocked=false,options={}){
 const context=await browser.newContext({viewport:{width,height:width<768?844:1024},...options,permissions:['clipboard-read','clipboard-write']});
 await context.route('**/*',route=>{if(route.request().url().startsWith(base)||route.request().url().startsWith('data:'))return route.continue();external.push(route.request().url());return route.abort();});
 const page=await context.newPage();lastPage=page;page.on('pageerror',err=>errors.push(err.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});page.on('request',r=>requests.push(r.url().startsWith('data:')?'data:image/jpeg;(normalized synthetic bitmap)':r.url()));
 await page.addInitScript(({key,s})=>{if(!localStorage.getItem(key))localStorage.setItem(key,JSON.stringify(s));},{key:M.KEY,s});
 await page.goto(base+'#home');if(blocked||s.schema===99)await page.getByRole('heading',{name:'Saved demo data needs attention',exact:true}).waitFor();else await page.locator('.hero h1').waitFor();return {page,context};
}
async function setWindows(page,windows){while(await page.locator('[data-time-row]').count()<windows.length)await page.getByRole('button',{name:'Add service time',exact:true}).click();while(await page.locator('[data-time-row]').count()>windows.length)await page.getByRole('button',{name:'Remove time '+await page.locator('[data-time-row]').count(),exact:true}).click();for(const [i,[start,end]]of windows.entries()){await page.getByLabel('Start time '+(i+1),{exact:true}).selectOption(String(start));await page.getByLabel('End time '+(i+1),{exact:true}).selectOption(String(end));}}
async function syntheticBitmap(page,type,width,height,noise=false){return Buffer.from(await page.evaluate(async({type,width,height,noise})=>{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#d86b3f';ctx.fillRect(0,0,width,height);ctx.fillStyle='#234c3d';ctx.fillRect(0,0,width/2,height/2);if(noise){const pixels=ctx.createImageData(width,height);let seed=98765;for(let i=0;i<pixels.data.length;i+=4){for(let channel=0;channel<3;channel++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;pixels.data[i+channel]=seed>>>24;}pixels.data[i+3]=255;}ctx.putImageData(pixels,0,0);}const blob=await new Promise(resolve=>canvas.toBlob(resolve,type,0.82));return Array.from(new Uint8Array(await blob.arrayBuffer()));},{type,width,height,noise}));}
const go=(page,hash)=>page.goto(base+'#'+hash);
async function signIn(page,email=owner){await page.locator('#signin-button').click();await page.getByLabel('Demo email',{exact:true}).selectOption(email);await page.getByRole('button',{name:'Continue',exact:true}).click();}
const modal=page=>page.getByRole('dialog');
async function finish(page){await modal(page).getByRole('button',{name:'Check original operation',exact:true}).click();}
async function check(name,fn){if(process.env.MEALFORWARD_QA_ONLY&&!name.startsWith(process.env.MEALFORWARD_QA_ONLY))return;try{await fn();results.push({name,status:'PASS'});console.log('PASS',name);}catch(err){results.push({name,status:'FAIL',error:err.message});if(lastPage&&!lastPage.isClosed()){await lastPage.screenshot({path:`${evidence}/failure.png`,fullPage:true});await writeFile(`${evidence}/failure.txt`,await lastPage.locator('body').innerText());}throw err;}}
async function overflow(page){assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'No horizontal viewport overflow');}
async function images(page){await page.locator('img').evaluateAll(imgs=>Promise.all(imgs.map(i=>{i.loading='eager';return i.decode();})));assert.ok(await page.locator('img').evaluateAll(imgs=>imgs.every(i=>i.complete&&i.naturalWidth>0)));}
async function english(page){const text=await page.locator('body').innerText();assert.ok(!/\p{Script=Han}/u.test(text),'Visible UI is English');assert.ok(await page.locator('[aria-label],img').evaluateAll(els=>els.every(el=>!/[\u3400-\u9fff]/u.test(el.getAttribute('aria-label')||el.getAttribute('alt')||''))));}
